    q_call_for_help: {
      id: "q_call_for_help",
      kind: "quest",
      label: "Cut Off",
      start: "before",
      stages: {
        before: { label: "Before", next: [{ to: "cut_off", when: "flag('storm_active')" }] },
        cut_off: {
          label: "The line is dead",
          next: [{ to: "find_fault", when: "flag('phone_tried')" }],
          objectives: [{ label: "Find out why the line is dead", when: "flag('phone_tried')" }],
          cue: "The hall telephone is silent and the gale has the whole fen in its grip; there is no knowing whether the causeway road will be passable by morning."
        },
        find_fault: {
          label: "Follow the line",
          next: [{ to: "repair", when: "at(pov, 'gatehouse') and flag('clue_phone_fault')" }, { to: "done", when: "flag('constable_called')" }],
          objectives: [{ label: "Walk to the gatehouse and examine Telephone junction box", when: "flag('clue_phone_fault')" }],
          hints: ["The line runs on poles from the gatehouse; a fallen bough is the usual culprit."]
        },
        repair: {
          label: "Mend the line",
          next: [{ to: "call", when: "flag('phone_working')" }, { to: "done", when: "flag('constable_called')" }],
          objectives: [{ label: "Splice the broken wire with tape and a screwdriver from Gardener's tool roll", when: "flag('phone_working')" }],
          hints: [
            "A steady hand and a Knowledge or Nerve check; the tool roll makes it much easier.",
            "The punt is the other way out, if the marsh is deep enough."
          ]
        },
        call: {
          label: "Telephone the constable",
          next: [{ to: "done", when: "flag('constable_called')" }],
          objectives: [{ label: "Use The hall telephone to reach Saltreach", when: "flag('constable_called')" }],
          gate: "flag('phone_working')"
        },
        done: {
          label: "Help is coming",
          next: [],
          effects: [{ type: "story.flag", args: { name: "constable_called", value: true } }],
          rewards: [
            {
              type: "relationships.adjust",
              args: { from: "gideon_pell", to: "pov", axis: "trust", delta: 15, why: "Pell is quietly grateful." }
            },
            {
              type: "relationships.adjust",
              args: { from: "lady_honoria", to: "pov", axis: "warmth", delta: 10, why: "Lady Honoria is grateful." }
            }
          ],
          cue: "The operator puts you through to the Saltreach post office, and a calm voice promises the constable within the hour and a half."
        }
      },
      visibility: "public"
    },
    s_thorne_death: {
      id: "s_thorne_death",
      kind: "secret",
      label: "The death of Sir Alaric",
      start: "before",
      stages: {
        before: { label: "Before", next: [{ to: "cue", when: "flag('body_found')" }] },
        cue: {
          label: "Heart failure?",
          next: [{ to: "s1_unnatural", when: "flag('clue_tincture_bottle') or flag('farrant_admitted')" }],
          cue: "Dr. Farrant says Sir Alaric's heart gave out in the night, as he always feared it would. Something about the library does not sit right."
        },
        s1_unnatural: {
          label: "Not an ordinary heart failing",
          next: [
            { to: "s2_motive", when: "(flag('clue_trust_ledger') or flag('clue_verity_memo'))" },
            { to: "s3_opportunity", when: "flag('clue_second_glass') + flag('clue_muddy_prints') + flag('clue_marsh_testimony') >= 2" }
          ],
          cue: "The doctor's heart tincture is a third gone, and Sir Alaric complained at dinner of seeing yellow haloes around the lamps. That is not an ordinary heart failing."
        },
        s2_motive: {
          label: "Money going out",
          next: [{ to: "s3_opportunity", when: "flag('clue_second_glass') + flag('clue_muddy_prints') + flag('clue_marsh_testimony') >= 2" }],
          cue: "For six years the Thorne Trust has paid out sums to 'M. Rutherford'. Someone has been robbing the family, and Sir Alaric had found out."
        },
        s3_opportunity: {
          label: "Someone shared a brandy",
          next: [{ to: "s4_culprit", when: "(flag('clue_trust_ledger') or flag('clue_verity_memo'))" }],
          cue: "Someone drank with Sir Alaric before eleven, left by the conservatory and washed a glass afterwards."
        },
        s4_culprit: {
          label: "One person, one reason, one chance",
          next: [{ to: "truth", when: "flag('accused') == 'julian_ashcombe' and flag('clue_trust_ledger')" }],
          cue: "Everything points at one person who had both the reason and the chance."
        },
        truth: {
          label: "What happened in the library",
          next: [],
          rewards: [],
          cue: "It all fits.",
          truth: "Julian Ashcombe, the family's solicitor and a trustee of the Thorne Trust, had taken about eleven thousand four hundred pounds over six years by paying it to a fictitious 'M. Rutherford'. Verity Lorne noticed the pattern while indexing the papers and told Sir Alaric on Thursday. Sir Alaric invited Ashcombe to confront him on Saturday after breakfast and asked the valuer to attend as an independent witness. At about five to eleven on Friday night Ashcombe fetched a clean glass from the kitchen; at five past he joined Sir Alaric in the library for a brandy to 'talk through the papers', and put a lethal dose of digitalis tincture, taken from Dr. Farrant's bag in the drawing room, into his host's glass. Sir Alaric's known heart condition and prescription meant that his death would pass as natural. Ashcombe rinsed his own glass, burned a page of the ledger, left by the conservatory door and went back to bed."
        }
      },
      visibility: "secret"
    },
    p_study_safe: {
      id: "p_study_safe",
      kind: "puzzle",
      label: "The study safe",
      start: "locked",
      stages: {
        locked: {
          label: "Four digits",
          next: [{ to: "open", when: "false" }],
          objectives: [{ label: "Open The study safe", when: "flag('safe_open')" }],
          cue: "A small brass plate on the safe's frame reads: 'Rebuilt, and kept.' The dial takes four digits.",
          answer: { expect: ["1887", "eighteen eighty-seven", "mdcccLXXXvii"], normalize: true, decision: { threshold: 0.8 } },
          hints: [
            "Sir Alaric was proud of one date. Look at the library mantel.",
            "The carved date is in Roman numerals.",
            "MDCCCLXXXVII is 1887: the year the west wing was rebuilt after the fire."
          ]
        },
        open: {
          label: "The safe swings open",
          next: [],
          effects: [
            { type: "story.flag", args: { name: "safe_open", value: true } },
            {
              type: "spawn",
              args: {
                id: "trust_ledger",
                kind: "item",
                name: "Thorne Trust account book",
                tier: "background",
                fields: { description: "A long green ledger recording six years of payments.", owner: "sir_alaric", weight_g: 1100 },
                relations: [{ type: "in", to: "study_safe" }]
              }
            }
          ],
          cue: "Inside: a thin bundle of letters and a long green account book."
        }
      },
      visibility: "known_by",
      owner: "study_safe"
    },
