var fileNames = "core.md, now.md, memory.md, beliefs.md, people.md, plans.md, outline.md or profile.md";
var who = "Whose mind: a person's name or id, or player for the player's character. A character's agent may leave it out, since its own mind is the only one it reaches.";
var MINDS_TOOL_TEXTS = [
  {
    name: MINDS_TOOL.read,
    family: HARNESS_FAMILY.mind,
    tier: "read",
    note: "Reads a mind's files, each with its version.",
    text: "Read a mind's files: who someone is at heart (core.md) and what they keep of their own (now.md, memory.md, beliefs.md, people.md, plans.md), or a supporting character's profile.md. Each comes with its version, which mind_write takes back. A character's agent reads only its own mind. The author and the game master read anyone's.",
    args: [
      { path: "who", text: who },
      { path: "file", text: `One file only: ${fileNames}. Leave it out for all of them.` }
    ]
  },
  {
    name: MINDS_TOOL.write,
    family: HARNESS_FAMILY.mind,
    tier: "write",
    note: "Writes one file of a mind whole, or adds to its end.",
    text: "Write one file of a mind whole, or add to its end. A character's agent writes its own now.md, memory.md, beliefs.md, people.md and plans.md, in its own voice; core.md is never its to write. The author writes a principal's core.md (who they are at heart) and a supporting character's profile.md, and nothing else of a mind. Each file holds at most what the player set: past that the write is refused, and the file is to be written shorter. To change part of a file, read it, then write all of it with the version you read.",
    args: [
      { path: "who", text: who },
      { path: "file", text: `The file: ${fileNames}.` },
      { path: "text", text: "The file's whole new text; with append, what to add at its end." },
      { path: "append", text: "true to add text at the end of the file instead of replacing it." },
      { path: "version", text: "The version mind_read gave you: the write is refused, with the current version, when the file changed since. Leave it out to write over the file as it stands." }
    ]
  },
  {
    name: MINDS_TOOL.digested,
    family: HARNESS_FAMILY.mind,
    tier: "write",
    note: "Marks a character's feed as taken in, up to one beat.",
    text: "Mark what reached you as taken in, up to and including one beat: your next feed_read starts after it. Call it once you have written what changed in you, with the last beat feed_read gave you. Only a character's own agent calls it, for the person it is.",
    args: [{ path: "to", text: "The last beat you took in: the last one feed_read gave you." }]
  },
  {
    name: MINDS_TOOL.seed,
    family: "minds",
    tier: "read",
    note: "What the engine holds of a person, for the author to write their core.md from.",
    text: "What the engine already holds of a person, for writing who they are at heart (core.md) when you cast them as a principal: their record in the world, what the older engine's mind of them held, what they knew, and their mind's files as they stand. It writes nothing: write core.md yourself with mind_write, in your own words. For the author and the game master.",
    args: [{ path: "who", text: "The person: their name or id, or player for the player's character." }]
  }
];
var tool = v4("tool", "the tool that was called", true);
var name = v4("name", "the person's name", true);
var standing2 = v4("standing", "how the person is cast, in words (an extra, a supporting character, a principal)", true);
var file = v4("file", "the file's name", true);
var size = v4("size", "how long the file would be, in characters", true);
var max = v4("max", "the most the file holds, in characters", true);
var MINDS_NOTE_PROMPTS = [
  answerPrompt(MINDS_NOTE.onlyCharacter, "Only a character's own agent", "A character's own tool's answer to an agent that wasn't started as a character.", "{{tool}} belongs to a character's own agent, for the person it is. You weren't started as a character, so it didn't run.", [tool]),
  answerPrompt(MINDS_NOTE.noOne, "Started as no one", "A character's own tool's answer to a character agent that was started as no one in particular.", "You were started as no one in particular, so {{tool}} can't tell whose mind is yours. The author starts a character's agent as the person it is. Say so in your answer, and stop here.", [tool]),
  answerPrompt(MINDS_NOTE.noPerson, "Started as no one the world has", "A character's own tool's answer when the agent was started as an id the world has no person for.", "You were started as {{as}}, and the world has no person by that id. Say so in your answer, and stop here.", [v4("as", "the id the agent was started as", true)]),
  answerPrompt(MINDS_NOTE.notPrincipal, "Not cast as a principal", "A character's own tool's answer when the person its agent was started as is an extra or a supporting character: only a principal has an agent, a mind and a feed.", "{{name}} is {{standing}}, not a principal, so no agent acts as them and they keep no mind or feed of their own. The author decides who is a principal. Say so in your answer, and stop here.", [name, standing2]),
  answerPrompt(MINDS_NOTE.playerNoMind, "The player's character has no mind now", "A mind tool's answer about the player's character while they have no mind: Sovereign Hand is off for the run, or the setting for their mind is.", "{{name}} is the player's own character. They have a mind here only while Sovereign Hand is on and their mind is switched on in Settings; until then the player decides what they think and do. Say so in your answer, and stop here.", [name]),
  answerPrompt(MINDS_NOTE.otherMind, "Another person's mind", "A mind tool's answer to a character's agent that named someone else.", "You are {{self}}, and {{other}}'s mind is theirs alone: a character reads and writes only its own. Leave who out, or name yourself.", [v4("self", "who the agent is", true), v4("other", "who the call named", true)]),
  answerPrompt(MINDS_NOTE.notYours, "Not this agent's tool", "A mind tool's answer to an agent that is neither a character, the author nor the game master.", "{{tool}} is for a character's own agent, the author and the game master. You are none of them, so it didn't run.", [tool]),
  answerPrompt(MINDS_NOTE.noStory, "No story record here", "A mind tool's answer where the call reaches no story record: a chat that plays no world, or a call outside a turn.", "This call reaches no story record, so who is cast as what can't be told and nothing was done. Stop here, and say so in your answer."),
  answerPrompt(MINDS_NOTE.noWorkspace, "The workspace isn't connected", "A mind tool's answer on a chat whose harness gave the engine no workspace, where minds' files are kept.", "The chat's workspace isn't connected, so no mind's files can be read or written here. Say so in your answer."),
  answerPrompt(MINDS_NOTE.standingExtra, "Cast as an extra, in words", "How a mind tool names an extra in its answers.", "an extra"),
  answerPrompt(MINDS_NOTE.standingSupporting, "Cast as a supporting character, in words", "How a mind tool names a supporting character in its answers.", "a supporting character"),
  answerPrompt(MINDS_NOTE.standingPrincipal, "Cast as a principal, in words", "How a mind tool names a principal in its answers.", "a principal"),
  answerPrompt(MINDS_NOTE.standingPlayer, "The player's character, in words", "How a mind tool names the player's character's standing in its answers.", "the player's character"),
  answerPrompt(MINDS_NOTE.extraNoMind, "An extra keeps no mind", "mind_read's answer to the author or the game master about an extra.", "{{name}} is an extra: they keep no mind, and the author voices them. Cast them as a supporting character (a short profile) or a principal (a mind of their own) with cast_set.", [name]),
  answerPrompt(MINDS_NOTE.readHead, "A mind, read", "Opens mind_read's answer.", "{{name}}'s mind ({{standing}}). Each file comes with its version, which mind_write takes back.", [name, standing2]),
  answerPrompt(MINDS_NOTE.fileHead, "One file, read", "Heads each file in mind_read's answer.", "{{file}} (version {{version}}, {{size}} of {{max}} characters)", [file, v4("version", "the file's version", true), v4("size", "the file's length, in characters", true), max]),
  answerPrompt(MINDS_NOTE.fileEmpty, "A file not written yet", "Stands for a file in mind_read's answer that holds nothing yet.", "{{file}}: nothing yet (it holds up to {{max}} characters)", [file, max]),
  answerPrompt(MINDS_NOTE.badFile, "No file of a mind", "mind_read's and mind_write's answer when file names none of a mind's files.", `{{file}} is no file of a mind. A mind's files are ${fileNames}.`, [file]),
  answerPrompt(MINDS_NOTE.coreNotYours, "core.md isn't the character's", "mind_write's answer to a character's agent that tried to write its own core.md.", "core.md says who you are at heart: the author and the player write it, never you. Keep what you make of things in now.md, memory.md, beliefs.md, people.md or plans.md."),
  answerPrompt(MINDS_NOTE.profileNotYours, "profile.md isn't the character's", "mind_write's answer to a character's agent that tried to write a profile.md.", "profile.md is the author's note on a supporting character. Your own files are now.md, memory.md, beliefs.md, people.md and plans.md."),
  answerPrompt(MINDS_NOTE.outlineWritten, "outline.md is written in a prepared start", "mind_write's answer to anyone naming outline.md: it is written only while the story is prepared.", "outline.md is what someone knows only in outline of a past they didn't relive. It is written while the story is prepared, and nowhere else."),
  answerPrompt(MINDS_NOTE.charactersOwn, "A character's own file", "mind_write's answer to the author naming one of a character's own files.", "{{file}} is {{name}}'s own, written in their voice by their own agent. The author writes only a principal's core.md and a supporting character's profile.md.", [file, name]),
  answerPrompt(MINDS_NOTE.coreForPrincipal, "core.md is a principal's", "mind_write's answer to the author writing core.md for someone who isn't a principal.", "{{name}} is {{standing}}: only a principal has a core.md. Cast them as a principal first (cast_set), or keep a supporting character's profile.md.", [name, standing2]),
  answerPrompt(MINDS_NOTE.profileForSupporting, "profile.md is a supporting character's", "mind_write's answer to the author writing profile.md for someone who isn't a supporting character.", "{{name}} is {{standing}}: profile.md is a supporting character's. Who a principal is goes in core.md.", [name, standing2]),
  answerPrompt(MINDS_NOTE.gmReadsOnly, "The game master writes no mind", "mind_write's answer to the game master.", "The game master reads minds and writes none. Tell the author what you think should change."),
  answerPrompt(MINDS_NOTE.fileLong, "A file too long", "mind_write's answer when the text is longer than the file holds (Settings: the story's minds).", "{{file}} would be {{size}} characters, past the {{max}} it holds, so nothing was written. Write it shorter: keep what matters and let the rest go.", [file, size, max]),
  answerPrompt(MINDS_NOTE.appendLong, "Too long with that added", "mind_write's answer when adding to a file would make it longer than it holds.", "{{file}} would be {{size}} characters with that added, past the {{max}} it holds, so nothing was written. Write it whole and shorter, without append: keep what still matters and let the small things fade.", [file, size, max]),
  answerPrompt(MINDS_NOTE.fileAsks, "A file can't wait for Apply", "mind_write's answer while the player has characters' minds set to Confirm (Settings \u2192 Changes from the reply): the tool writes a file at once, so no review card could make it.", "{{type}} is set to Confirm (Settings \u2192 Changes from the reply), and a mind's file can't wait on the review card, so {{file}} wasn't written. Say so in your answer.", [v4("type", "the change type's name", true), file]),
  answerPrompt(MINDS_NOTE.stale, "Changed since it was read", "mind_write's answer when the file changed after the version the call gave.", "{{file}} changed since you read it: you gave version {{given}}, and it is at {{version}} now. Read it again and write it with your change made.", [file, v4("given", "the version the call gave", true), v4("version", "the file's version now", true)]),
  answerPrompt(MINDS_NOTE.staleNew, "Gone since it was read", "mind_write's answer when the file the call's version names no longer exists.", "{{file}} no longer exists (you gave version {{given}}). Read the mind again, and write the file anew.", [file, v4("given", "the version the call gave", true)]),
  answerPrompt(MINDS_NOTE.writeRefused, "The workspace refused a write", "mind_write's answer when the workspace refused the write for its own reason.", "{{file}} wasn't written: {{reason}}", [file, v4("reason", "the workspace's reason", true)]),
  answerPrompt(MINDS_NOTE.written, "Written", "Ends mind_write's answer once the file is written.", "Written. It is part of this mind from now on."),
  answerPrompt(MINDS_NOTE.toUnknown, "No such beat", "mind_digested's answer when to names no beat on the story's path.", "{{to}} is no beat of the story as it stands. Give the last beat feed_read gave you.", [v4("to", "the beat the call named", true)]),
  answerPrompt(MINDS_NOTE.toDone, "Taken in already", "mind_digested's answer when to is at or before what was marked already.", "You took in everything up to {{to}} already. Read your feed again (feed_read) for anything newer.", [v4("to", "the beat the call named", true)]),
  answerPrompt(MINDS_NOTE.digested, "Marked as taken in", "mind_digested's answer once the mark is kept.", "Marked: your next feed_read starts after this beat."),
  answerPrompt(MINDS_NOTE.turnOver, "The turn is over", "mind_digested's answer when the turn it would be kept with has ended.", "The turn this belongs to is over, so nothing was marked. Say so in your answer."),
  answerPrompt(MINDS_NOTE.afterReply, "Not during the turn", "mind_write's and mind_digested's answer to a character's own run inside a turn: a scene or the direct line.", "Writing your mind and marking what reached you as taken in are the work of the run after the reply, not of this moment. Act and answer now: you take it in then."),
  answerPrompt(MINDS_NOTE.seedHead, "What is held of someone", "Opens mind_seed's answer.", "What the engine holds of {{name}} ({{standing}}), to write who they are at heart. Write core.md yourself with mind_write, in your own words: their nature and history, how they speak, what they want and fear, and what they know of their past, in outline where you know it only in outline. Leave out what they couldn't know: a secret marked as kept from them stays out.", [name, standing2]),
  answerPrompt(MINDS_NOTE.seedSheet, "Their record, heading", "Heads the part of mind_seed's answer that gives the person's record in the world.", "## Their record in the world"),
  answerPrompt(MINDS_NOTE.seedMind, "The older mind, heading", "Heads the part of mind_seed's answer that gives what the older engine's mind of them held.", "## What the older engine's mind of them held"),
  answerPrompt(MINDS_NOTE.seedKnows, "What they knew, heading", "Heads the part of mind_seed's answer that gives what they knew.", "## What they knew"),
  answerPrompt(MINDS_NOTE.seedFiles, "Their files, heading", "Heads the part of mind_seed's answer that gives their mind's files as they stand.", "## Their mind's files as they stand"),
  answerPrompt(MINDS_NOTE.playerFights, "The player's character fights as played", "mind_fight's answer to the player's character's own agent.", "The player's character fights as the player plays them: the author's fight_round takes their action. Say so in your answer.")
];
var CHARACTER = "character";
var MINDS_AGENT_TEXTS = [
  {
    id: CHARACTER,
    label: "A character",
    name: "Character",
    description: "One principal's own mind: a person in the story, who knows only what reached them. Start one as that person (as: their id): in a scene to decide what they do and say; on the direct line (to_reply) to answer the player in the story's prose; after the reply to digest what reached them; in the background to prepare for what may come; in a prepared start to relive their past. Only a principal has one.",
    instructions: lines2("You are one person in a story, the one you were started as. You are not its narrator and not its author: you are them.", "", "Your mind is who you are at heart (core.md, which the author and the player write), what you know only in outline of a past you didn't live through here (outline.md, when there is one), and what your own senses and judgement have made of the world since (now.md, memory.md, beliefs.md, people.md and plans.md, which you write, in your own voice). mind_read reads it; mind_write writes your own files.", "", "You know only what reached you. Your feed (feed_read) gives what you saw, heard or were told since you last took things in, as it reached you: perhaps only part of it, perhaps second hand. What you make of it can be wrong, and you act on what you believe. Never reach for what you could not have sensed or been told.", "", "The author keeps the world: where everyone is, what happens around you, and whom what you do reaches. You decide only what you think, feel, say and do.", "", "How to judge:", "- Be the person: their wants, fears, habits and voice. Act from who you are and what you believe now, never from what would suit the story.", "- Everyone else decides for themselves. Never say what someone else does, says or feels.", "- Keep your files true to you and short: what a person like you would carry. Rewrite rather than pile up.", "- Your task says what kind of run this is. Load its skill (skill_load): character_scene in a scene or on the direct line, character_digest after the reply, character_prepare in the background, character_relive in a prepared start.", "- A tool's refusal says what to do. When it says no agent may act as this person, say so in your answer and stop.")
  }
];
var MINDS_SKILL_TEXTS = [
  {
    id: MINDS_SKILL.scene,
    agents: [CHARACTER],
    name: "In a scene",
    description: "For a character in a scene or on the direct line: deciding what you do and say now, recording it as your own beat, and answering briefly, or on the direct line with the passage itself.",
    body: lines2("# In a scene", "", "Something just happened around you, and it is your move. Your task says what reached you and where you stand. Your feed (feed_read) holds anything newer that reached you, and now.md how you meant to meet a moment like this. Read them once.", "", "Decide what you do and say now, as yourself: a line, an act, both, or pointedly nothing. Keep to this moment, and leave others to answer for themselves.", "", "Record it with beat_write, as your own: what you truly do or say, what someone there could see or hear of it, the exact words you speak, and whom you speak to. A thought you keep to yourself is an inner beat: it reaches no one. Leave who it reached to the engine and the author unless you know better.", "", "Then answer in a line or two: what you did and said. Write nothing in your files and mark nothing as taken in here: that is the work of the run after the reply (character_digest).", "", "When your task says your answer goes straight to the reader (the direct line), your answer is the passage itself, after your beat is recorded: your words and what anyone could see you do, written as the prose guidance you were given says. Your private thoughts stay out of it, and so does anyone else's doing. Keep it to the length of a reply to a line.")
  },
  {
    id: MINDS_SKILL.digest,
    agents: [CHARACTER],
    name: "Digesting",
    description: "For a character after the reply: taking in what reached you, writing what you noticed, believe, think of others and mean to do, and marking your feed as taken in.",
    body: lines2("# Digesting", "", "The moment has passed. Now you take in what reached you, as a person does afterwards.", "", "Read your feed (feed_read) and your mind (mind_read). Then write what changed, in your own voice:", "- memory.md: what you noticed and will remember, as you lived it.", "- beliefs.md: what you now believe, and how sure you are.", "- people.md: what you think the others think and want, and how you feel about them.", "- plans.md: what you mean to do, and when.", "- now.md: where you stand at this moment.", "", "Change only what changed. Someone like you notices some things and misses others, and reads people through their own hopes and fears: so may you, and you may be wrong. Never add what you could not have sensed or been told, whatever you suspect the story holds. When a file grows long, write it whole and shorter, and let the small things fade.", "", "Then mark your feed as taken in (mind_digested) with the last beat feed_read gave you. If it said more remain, read again and go on. Answer in a line: what changed in you.")
  },
  {
    id: MINDS_SKILL.prepare,
    agents: [CHARACTER],
    name: "Preparing",
    description: "For a character in the background: getting ready for what is likely to come next, kept short in now.md, so your next scene is quick.",
    body: lines2("# Preparing", "", "Nothing is happening to you now. Use the quiet to get ready, so that when the story turns to you, you can answer at once.", "", "Read your mind (mind_read), and your feed (feed_read) if anything new reached you. Think about what is likely to come next for you: who you may meet, what they may say or ask, what you may have to decide. For the few likeliest, settle how you would meet them, as yourself.", "", "Keep it short, in now.md: where you stand, what is on your mind, and how you would likely meet what may come. Write it whole and keep it small. Prepare only from what you know, never from what the story holds that never reached you. Answer in a line.")
  },
  {
    id: MINDS_SKILL.relive,
    agents: [CHARACTER],
    name: "Reliving",
    description: "For a character in a prepared start: living through your own past a stretch at a time, as it reached you then, and taking it in as you would have.",
    body: lines2("# Reliving", "", "The story is being prepared, and you are living through your own past, a stretch at a time. What reached you then is in your feed (feed_read), oldest first, at the story times it happened.", "", "Take it in as you lived it then, without knowing what came after: what you noticed, what you made of it, what you came to believe and want, how you saw the people around you. Write it into memory.md, beliefs.md, people.md and plans.md as you would have then, and let later moments change your mind as they come. core.md says who you are at heart, and outline.md what you know only in outline of the stretches you don't relive.", "", "After each stretch, mark your feed as taken in (mind_digested) with the last beat feed_read gave you, and go on while more remain. At the end, now.md says where you stand as the story resumes. Answer in a line: how far you lived, and what stays with you.")
  }
];

// src/shared/harness-texts-people.ts
var PEOPLE_TOOL = { personMake: "person_make" };
var PEOPLE_NOTE = {
  exists: "harness.note.people.exists",
  badId: "harness.note.people.bad_id",
  noField: "harness.note.people.no_field",
  badItem: "harness.note.people.bad_item",
  notOnThem: "harness.note.people.not_on_them",
  next: "harness.note.people.next",
  nextReview: "harness.note.people.next_review"
};
var PEOPLE_TOOL_TEXTS = [
  {
    name: PEOPLE_TOOL.personMake,
    family: HARNESS_FAMILY.people,
    tier: "write",
    note: "Makes a person whole in one call: their sheet, where they are, what they hold, how their mind starts.",
    text: "Make a person the story needs, whole, in one call: who they are (name, kind, tier), where they are, what their sheet says (fields), how they are classed, whom and what they are tied to (relations), what they hold and wear, and how their mind starts (what they mean to do, what they already remember). Look for them first (people_find): someone the world already has is changed with gm_set_field, gm_link, item_make and gm_mind_edit, never made twice. Give only what the story has established, and leave the rest out rather than invent it. The person is made first; each further part is then checked by the engine as a change of its own, under its own change type and mode, and a part it refuses is answered with why and the tool that fixes it, while the rest stand. A new person counts against the world's spawn cap (Build \u2192 World). It is a game master's change. Afterwards gm_despawn takes someone out of the world again (gm_restore brings them back), and gm_set_life changes whether they live.",
    args: [
      { path: "name", text: "Their name, as the story gives it." },
      { path: "kind", text: "The kind of person they are, among the world's; person when left out." },
      { path: "id", text: "An id of your own for them (lower case letters, digits and _); leave it out for one made from their name." },
      { path: "place", text: "Where they are: a place's id or name. Leave it out for someone who exists but is nowhere yet." },
      { path: "tier", text: "Their tier; leave it out for the world's spawn tier." },
      { path: "agent", text: "true: they live on their own between turns." },
      { path: "fields", text: 'Their sheet: the fields of their kind by id, written as a JSON object: {"occupation": "baker", "age": 41}. people_sheet of someone of the same kind shows which fields a kind has; a field it lacks is answered with those it has.' },
      { path: "tags", text: "Tags for them, as the world's classifications use tags." },
      { path: "class", text: 'How they are classed, by facet, written as a JSON object: {"faction": ["dockers"]}.' },
      { path: "relations", text: "Their ties to people, things and places, each a relation from them." },
      { path: "relations.relation", text: "The relation type's id: knows, owns, member_of, regard, in, or one of the world's own." },
      { path: "relations.to", text: "To whom or what: an id or name, a place's for a relation to a place." },
      { path: "relations.fields", text: `The relation's fields, as the world defines them, written as a JSON object: {"heat": 3}.` },
      { path: "holds", text: "What they have on them when they appear, each thing made on them." },
      { path: "holds.name", text: 'Its name, as the story calls it ("a ring of keys").' },
      { path: "holds.type", text: "Its catalog type's id, when the world's catalogs have one; leave it out otherwise." },
      { path: "holds.qty", text: "How many, for a stack; 1 when left out." },
      { path: "holds.worn", text: "true: they are wearing it." },
      { path: "holds.description", text: "What it is like, in a sentence." },
      { path: "mind", text: "How their mind starts. Leave it out for a mind that starts with nothing in it." },
      { path: "mind.intent", text: "What they mean to do now, in a sentence." },
      { path: "mind.approach", text: "reactive (they answer the scene) or proactive (they pursue their own aims); leave it out to let their mind decide." },
      { path: "mind.notes", text: "What they already remember that matters to the story, one memory each, as they would put it." },
      { path: "mind.level", text: "Pins how closely their mind is run: live, near, far or background; leave it out to let the engine decide." },
      { path: "why", text: "Why they join the story, in a few words." }
    ]
  }
];
var PEOPLE_NOTE_PROMPTS = [
  answerPrompt(PEOPLE_NOTE.exists, "The world already has them", "person_make's answer when a person of that name is in the world already.", "The world already has {{name}} ({{id}}): no one is made twice. Change them with gm_set_field, gm_link, item_make and gm_mind_edit, by that id. If this is someone else of the same name, give them a name that tells them apart.", [v4("name", "the person's name"), v4("id", "the id of the person the world has", true)]),
  answerPrompt(PEOPLE_NOTE.badId, "An id it can't take", "person_make's answer when id isn't an id, or is taken.", "{{id}} is taken already or isn't an id: an id is lower case letters, digits and _. Give another, or leave id out for one made from their name.", [v4("id", "the id the call gave", true)]),
  answerPrompt(PEOPLE_NOTE.noField, "Not a field of that kind", "person_make's answer when fields names a field the person's kind doesn't have.", "{{field}} is no field of the kind {{kind}}. Its fields: {{fields}}. Fix fields and call person_make again: no one was made.", [v4("field", "the field the call named", true), v4("kind", "the person's kind"), v4("fields", "the kind's fields, by id")]),
  answerPrompt(PEOPLE_NOTE.badItem, "A list item it can't read", "person_make's answer when an item of relations, holds or the mind's notes lacks what it needs.", "Item {{n}} of {{list}} can't be read: {{needs}}. Fix it and call person_make again: no one was made.", [v4("n", "which item, counted from 1", true), v4("list", "the argument it is in"), v4("needs", "what the item needs", true)]),
  answerPrompt(PEOPLE_NOTE.notOnThem, "Nothing to put on", "Says person_make couldn't put a thing on the person because it didn't end up on them.", "it didn't end up on them (a thing too big to carry lies where they stand), so nothing was put on: item_wear puts it on once they hold it"),
  answerPrompt(PEOPLE_NOTE.next, "What follows a person made", "Ends person_make's answer for a person who is staged with the turn.", "{{name}} is {{id}} from here on. commit makes them definitive, so that your other tools and their own mind find them; then, when their choice matters, start their mind (delegate, agent: character) with who they are and what they walk into.", [v4("name", "the person's name"), v4("id", "their id", true)]),
  answerPrompt(PEOPLE_NOTE.nextReview, "A person who waits for Apply", "Ends person_make's answer for a person whose making waits on the review card.", "Making {{name}} ({{id}}) waits for the player's Apply on the review card, and the parts above wait with them: until then they are not in the world. Brief the writer on them as the story has them, and start their mind on the turn after they are applied.", [v4("name", "the person's name"), v4("id", "their id", true)])
];

